choose.when:
select date_value from t_ds_calendar_date where calendar_id = #{calendarId} and date_value > #{baseDate}
and is_trading_day = 1
order by date_value asc offset #{offsetDays} - 1 limit 1

select date_value from t_ds_calendar_date where calendar_id = #{calendarId} and date_value < #{baseDate}
and is_trading_day = 1
order by date_value desc offset abs(#{offsetDays}) - 1 limit 1

choose.otherwise:

select max(date_value) 
from t_ds_calendar_date 
where calendar_id = #{calendarId}
and date_value <= #{baseDate}

    and is_trading_day = 1
